verus! {

fn r_(a: Vec<i8>, b: Vec<i8>) -> Vec<i8>
    ensures
        |result| == |a| + |b|,
        // Elements from a are preserved in order
        forall(|i: usize| (i < |a|) ==> result[i] == a[i]),
        // Elements from b are preserved in order, shifted by |a|
        forall(|j: usize| (j < |b|) ==> result[|a| + j] == b[j]),
{
    let mut result = Vec::new();
    let mut i: usize = 0;
    // Append a’s elements to result
    while i < a.len()
        invariant
            i <= a.len(),
            |result| == i,
            forall(|k: usize| (k < i) ==> result[k] == a[k]),
            forall(|k: usize| (i <= k && k < |result|) ==> false),
        decreases a.len() - i,
    {
        result.push(a[i]);
        i += 1;
    }
    let mut j: usize = 0;
    // Append b’s elements after a’s elements
    while j < b.len()
        invariant
            j <= b.len(),
            |result| == |a| + j,
            forall(|k: usize| (k < |a|) ==> result[k] == a[k]),
            forall(|k: usize| (k >= |a| && k < |a| + j) ==> result[k] == b[k - |a|]),
        decreases b.len() - j,
    {
        result.push(b[j]);
        j += 1;
    }
    result
}

}
